package com.veyra.booking;import com.veyra.security.CurrentUser;import com.veyra.shared.ApiException;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;@RestController @RequestMapping("/api/v1/bookings")public class NoShowController{private final JdbcTemplate db;public NoShowController(JdbcTemplate d){db=d;}@PostMapping("/{id}/no-show")Map<String,Object>noShow(@PathVariable UUID id){UUID driver=db.queryForObject("select id from drivers where user_id=?",UUID.class,CurrentUser.id());Map<String,Object>b=db.queryForMap("select selected_driver_id,status,scheduled_at from scheduled_bookings where id=?",id);if(!driver.equals(b.get("selected_driver_id"))||!"DRIVER_ARRIVED".equals(b.get("status")))throw new ApiException(HttpStatus.FORBIDDEN,"NO_SHOW_NOT_ALLOWED");if(OffsetDateTime.now().isBefore(((OffsetDateTime)b.get("scheduled_at")).plusMinutes(15)))throw new ApiException(HttpStatus.TOO_EARLY,"WAIT_PERIOD_NOT_FINISHED");db.update("update scheduled_bookings set status='CUSTOMER_NO_SHOW',updated_at=now() where id=?",id);return Map.of("status","CUSTOMER_NO_SHOW");}}